1962	  version.set_schema(*schema_);
1963	  version.set_enable_mmap(options_.enable_mmap_);
1964	  version.reset_writing_segment_meta(writing_segment_->meta());
1965	  version.set_id_map_path_suffix(0);
1966	  version.set_delete_snapshot_path_suffix(0);
1967	  version.set_next_segment_id(1);
1968	
1969	  version_manager_->apply(version);
1970	  s = version_manager_->flush();
1971	  CHECK_RETURN_STATUS(s);
1972	
1973	  segment_id_allocator_.store(1);
1974	  segment_manager_ = std::make_unique<SegmentManager>();
1975	
1976	  return Status::OK();
1977	}
