15	#include "local_wal_file.h"
16	#ifndef _MSC_VER
17	#include <unistd.h>
18	#endif
19	#include <zvec/ailego/hash/crc32c.h>
20	#include <zvec/ailego/logger/logger.h>
21	#include "db/common/error_code.h"
22	#include "db/common/file_helper.h"
23	#include "db/common/typedef.h"
24	
25	#define MAX_RECORD_SIZE 4194304  // 4Mb
26	
27	namespace zvec {
28	
29	int LocalWalFile::append(std::string &&data) {
30	  WalRecord record;
31	  record.length_ = data.size();
32	  record.crc_ = ailego::Crc32c::Hash(
33	      reinterpret_cast<const void *>(data.data()), record.length_, 0);
34	  record.content_ = std::forward<std::string>(data);
35	
36	  if (write_record(record) < 0) {
37	    WLOG_ERROR("Wal write record error. record.length_[%zu]",
38	               (size_t)record.length_);
39	    return -1;
40	  }
41	  // if max_docs_wal_flush_ is 0, no need flush
42	  if (max_docs_wal_flush_ != 0 && docs_count_ >= max_docs_wal_flush_) {
43	    if (!file_.flush()) {
44	      WLOG_ERROR("Wal flush error. docs_count_[%zu] max_docs_wal_flush_[%zu]",
45	                 (size_t)docs_count_, (size_t)max_docs_wal_flush_);
46	    }
47	    docs_count_ = 0;
48	  }
49	  return 0;
50	}
51	
52	std::string LocalWalFile::next() {
53	  WalRecord record;
54	  if (read_record(record) > 0) {
55	    uint32_t tmp_crc = ailego::Crc32c::Hash(
56	        reinterpret_cast<const void *>(record.content_.data()), record.length_,
57	        0);
58	    if (tmp_crc == record.crc_) {
59	      return std::move(record.content_);
60	    } else {
61	      WLOG_ERROR(
62	          "Wal next error. record.length_[%zu] crc_[%zu] != tmp_crc[%zu]",
63	          (size_t)record.length_, (size_t)record.crc_, (size_t)tmp_crc);
64	    }
65	  }
66	  // end of file or read error
67	  return std::string();
68	}
69	
70	int LocalWalFile::open(const WalOptions &wal_option) {
71	  CHECK_STATUS(opened_, false);
72	  if (wal_option.create_new) {
73	    if (FileHelper::FileExists(wal_path_)) {
74	      WLOG_ERROR("Wal open error. file already exist create_new[%d]",
75	                 wal_option.create_new);
76	      return -1;
77	    }
78	
79	    if (!file_.create(wal_path_, false)) {
80	      WLOG_ERROR("Wal create error. create_new[%d]", wal_option.create_new);
81	      return -1;
82	    }
83	
84	    // write wal header
85	    int write_size = file_.write((const void *)&header_, sizeof(header_));
86	    if (write_size != sizeof(header_)) {
87	      WLOG_ERROR("Wal write header error. create_new[%d]",
88	                 wal_option.create_new);
89	      return -1;
90	    }
91	
92	  } else {
93	    if (!FileHelper::FileExists(wal_path_)) {
94	      WLOG_ERROR("Wal open error. file is not exist create_new[%d]",
95	                 wal_option.create_new);
96	      return -1;
97	    }
98	
99	    if (!file_.open(wal_path_.c_str(), false)) {
100	      WLOG_ERROR("Wal open error. create_new[%d]", wal_option.create_new);
101	      return -1;
102	    }
103	
104	    // open default for write
105	    file_.seek(0, ailego::File::Origin::End);
106	  }
107	
108	  max_docs_wal_flush_ = wal_option.max_docs_wal_flush;
109	  opened_ = true;
110	
111	  WLOG_INFO("Wal open success. create_new[%d]", wal_option.create_new);
112	  return 0;
113	}
114	
115	int LocalWalFile::close() {
116	  CHECK_STATUS(opened_, true);
117	  file_.close();
118	  WLOG_INFO("Wal close success");
119	  opened_ = false;
120	  return 0;
121	}
122	
123	int LocalWalFile::remove() {
124	  if (opened_) {
125	    close();
126	  }
127	  if (FileHelper::FileExists(wal_path_)) {
128	    FileHelper::RemoveFile(wal_path_);
129	    WLOG_INFO("Wal remove success.");
130	  }
131	  return 0;
132	}
133	
134	int LocalWalFile::flush() {
135	  CHECK_STATUS(opened_, true);
136	  if (!file_.flush()) {
137	    WLOG_ERROR("Wal flush error.");
138	    return -1;
139	  }
140	  return 0;
141	}
142	
143	int LocalWalFile::prepare_for_read() {
144	  CHECK_STATUS(opened_, true);
145	  if (!file_.seek(0, ailego::File::Origin::Begin)) {
146	    return -1;
147	  }
148	  int read_size = file_.read((void *)&header_, sizeof(header_));
149	  if (read_size != sizeof(header_)) {
150	    WLOG_ERROR("Wal read header error.");
151	    return -1;
152	  }
153	  if (header_.wal_version != 0UL) {
154	    WLOG_ERROR("Wal version not support error.");
155	    return -1;
156	  }
157	  return 0;
158	}
159	
160	//! Return 1 if success or -1 if write error
161	int LocalWalFile::write_record(WalRecord &record) {
162	  CHECK_STATUS(opened_, true);
163	
164	  int write_size = 0;
165	  int ret = -1;
166	
167	  std::lock_guard<std::mutex> lock(file_mutex_);
168	  do {
169	    write_size = file_.write((const void *)&record.length_, LENGTH_SIZE);
170	    if (write_size != LENGTH_SIZE) {
171	      WLOG_ERROR("Wal write error. record.length_ error write_size[%d]",
172	                 write_size);
173	      break;
174	    }
175	
176	    write_size = file_.write((const void *)&record.crc_, CRC_SIZE);
177	    if (write_size != CRC_SIZE) {
178	      WLOG_ERROR("Wal write error. record.crc_ error write_size[%d]",
179	                 write_size);
180	      break;
181	    }
182	
183	    write_size =
184	        file_.write((const void *)record.content_.data(), record.length_);
185	    if (write_size != (int)record.length_) {
186	      WLOG_ERROR("Wal write error. record.content_ error write_size[%d]",
187	                 write_size);
188	      break;
189	    }
190	    ret = 1;  // write one record success
191	    docs_count_++;
192	  } while (false);
193	
194	  return ret;
195	}
196	
197	//! Return 1 if success or 0 if eof or -1 if read error
198	int LocalWalFile::read_record(WalRecord &record) {
199	  CHECK_STATUS(opened_, true);
200	
201	  int read_size = 0;
202	  std::string err_msg;
203	  int ret = -1;
204	
205	  do {
206	    read_size =
207	        file_.read(reinterpret_cast<void *>(&record.length_), LENGTH_SIZE);
208	    if (read_size == 0) {
209	      ret = 0;
210	      WLOG_INFO("Wal read finished. end of file");
211	      break;
212	    }
213	
214	    if (read_size != LENGTH_SIZE) {
215	      WLOG_ERROR("Wal read error. record.length_ error read_size[%d]",
216	                 read_size);
217	      break;
218	    }
219	
220	    read_size = file_.read(reinterpret_cast<void *>(&record.crc_), CRC_SIZE);
221	    if (read_size != CRC_SIZE) {
222	      WLOG_ERROR("Wal read error. record.crc_ error read_size[%d]", read_size);
223	      break;
224	    }
225	
226	    // resize may crash if record.length_ very large
227	    if (record.length_ <= 0 || record.length_ > MAX_RECORD_SIZE) {
228	      WLOG_ERROR("Wal read error. record.length_ value error read_size[%d]",
229	                 read_size);
230	      break;
231	    }
232	
233	    record.content_.resize(record.length_);
234	    read_size = file_.read((void *)const_cast<char *>(record.content_.data()),
235	                           record.length_);
236	    if (read_size != (int)record.length_) {
237	      WLOG_ERROR("Wal read error. record.content_ error read_size[%d]",
238	                 read_size);
239	      break;
240	    }
241	    ret = 1;  // read one record success
242	  } while (false);
243	
244	  return ret;
245	}
246	
247	};  // namespace zvec

