1882	Status SegmentImpl::reload_vector_index(
1883	    const CollectionSchema &schema, const SegmentMeta::Ptr &new_segment_meta,
1884	    const std::unordered_map<std::string, VectorColumnIndexer::Ptr>
1885	        &vector_indexers,
1886	    const std::unordered_map<std::string, VectorColumnIndexer::Ptr>
1887	        &quant_vector_indexers) {
1888	  collection_schema_ = std::make_shared<CollectionSchema>(schema);
1889	  segment_meta_ = new_segment_meta;
1890	  fresh_persist_block_offset();
1891	
1892	  auto vector_fields = schema.vector_fields();
1893	
1894	  for (auto field : vector_fields) {
1895	    auto vector_index_params =
1896	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
1897	
1898	    if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
1899	      auto iter = vector_indexers.find(field->name());
1900	      if (iter != vector_indexers.end()) {
1901	        auto indexers = vector_indexers_[field->name()];
1902	        for (auto indexer : indexers) {
1903	          auto s = indexer->Destroy();
1904	          CHECK_RETURN_STATUS(s);
1905	        }
1906	        vector_indexers_[field->name()] = {iter->second};
1907	      }
1908	      auto q_iter = quant_vector_indexers_.find(field->name());
1909	      if (q_iter != quant_vector_indexers_.end()) {
1910	        auto q_indexers = q_iter->second;
1911	        for (auto q_indexer : q_indexers) {
1912	          auto s = q_indexer->Destroy();
1913	          CHECK_RETURN_STATUS(s);
1914	        }
1915	        quant_vector_indexers_.erase(q_iter);
1916	      }
1917	    } else {
1918	      auto iter = vector_indexers.find(field->name());
1919	      if (iter != vector_indexers.end()) {
1920	        auto indexers = vector_indexers_[field->name()];
1921	        for (auto indexer : indexers) {
1922	          auto s = indexer->Destroy();
1923	          CHECK_RETURN_STATUS(s);
1924	        }
1925	        vector_indexers_[field->name()] = {iter->second};
1926	      }
1927	      auto q_iter = quant_vector_indexers.find(field->name());
1928	      if (q_iter != quant_vector_indexers.end()) {
1929	        auto q_indexers = quant_vector_indexers_[field->name()];
1930	        for (auto q_indexer : q_indexers) {
1931	          auto s = q_indexer->Destroy();
1932	          CHECK_RETURN_STATUS(s);
1933	        }
